mapper.select:
SELECT sbdi.handle_status AS tabFlag, count(distinct sbdid.id) AS count FROM so_b2c_delivery_intercept_detail sbdid LEFT JOIN so_b2c_delivery_intercept sbdi ON sbdid.main_id = sbdi.id AND sbdi.is_deleted = FALSE LEFT JOIN so_b2c_delivery sbd ON sbd.id = sbdi.delivery_id AND sbd.is_deleted = FALSE WHERE sbdid.is_deleted = FALSE
${params.permissionSql}
GROUP BY sbdi.handle_status

SELECT sbdi.id, sbdi.code, sbdi.source_type, sbdi.so_code, sbdi.so_delivery_code, sbdi.so_outstock_code, sbdid.sku_id, sbdid.sku_no, sbdid.delivery_qty, sbdid.warehouse_id, sbdid.warehouse_name, sbdi.logistics_channel_id, sbdi.logistics_channel_name, sbdi.bill_type, sbdi.transport_no, sbdi.cancel_status, sbdi.intercept_status, sbdi.handle_status, sbdi.handle_result, sbdi.remark, sbdi.create_user_name, sbdi.handle_user_name, sbdi.create_time, sbdi.handle_time, sb.shop_id, sb.platform_code as platformOrderCode FROM so_b2c_delivery_intercept_detail sbdid LEFT JOIN so_b2c_delivery_intercept sbdi ON sbdid.main_id = sbdi.id AND sbdi.is_deleted = FALSE LEFT JOIN so_b2c sb on sb.id = sbdi.so_id and sb.is_deleted =false WHERE sbdid.is_deleted = FALSE
and ${params.sqlMap.default}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sbdi.create_time desc
